import os
import torch


class Config:
    """
    Global configuration for the Orthogonal MIP-Texture Hybrid Quantile-Elastic Pipeline.
    """

    # =========================================================================
    # PATHS
    # =========================================================================
    INPUT_DIR = "./input"
    TRAIN_DIR = os.path.join(INPUT_DIR, "train")
    TEST_DIR = os.path.join(INPUT_DIR, "test")

    # Metadata generated by the metadata script
    METADATA_DIR = "./metadata"
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Working and Cache Directories
    WORKING_DIR = "./working"
    # Specific cache directory for this idea (Idea 13)
    CACHE_DIR = os.path.join(WORKING_DIR, "idea_13")

    # Submission
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # IMAGE PREPROCESSING
    # =========================================================================
    # Target image size for EfficientNet-B0
    IMG_SIZE = 224

    # Hounsfield Unit (HU) Windowing for Lung Tissue
    HU_MIN = -1000
    HU_MAX = -400

    # Structural Sampling
    NUM_TOP_VARIANCE_SLICES = 3
    NUM_MIPS = 3  # Axial, Coronal, Sagittal
    TOTAL_IMAGES_PER_PATIENT = NUM_TOP_VARIANCE_SLICES + NUM_MIPS

    # =========================================================================
    # MODEL HYPERPARAMETERS
    # =========================================================================
    SEED = 42

    # Dimensionality Reduction
    N_PCA_COMPONENTS = 50

    # Feature Extractor (EfficientNet) Settings
    BATCH_SIZE = 32
    NUM_WORKERS = 4
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Linear Models Settings
    # For Quantile Regressor and ElasticNet
    MAX_ITER = 10000

    # =========================================================================
    # DEVELOPMENT / DEBUGGING
    # =========================================================================
    # If True, runs on a small subset of data
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 10

    @classmethod
    def setup(cls):
        """
        Ensures that necessary working and submission directories exist.
        """
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

        # Set deterministic behavior for PyTorch
        torch.manual_seed(cls.SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(cls.SEED)
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
